window.LN_PRACTICE_BANK.questions.push(...[{"id":"dc-test-31-01","course":"electrical-machines","sections":["dc-chapter-test","dc-sec31"],"title":"为什么电刷端可以得到单向电压","type":"single","prompt":"一台具有换向器的两极有刷直流发电机，原动机保持方向和速度，线圈边交替经过N、S极。电刷端电压为何可基本保持同一极性？","steps":["沿同一物理线圈追踪它在两极下的电势符号。","线圈转过半周后，换向片与固定电刷的接触对象发生变化。","电刷相当于随旋转周期交换接线，输出虽有脉动，平均极性可维持。"],"transfer":"若去掉换向器，直接使用两个滑环，线圈外端口电压波形会怎样变化？","skills":["因果与证据","解释表达"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"沿同一物理线圈追踪它在两极下的电势符号。","options":[{"id":"a","text":"线圈本身的感应电动势不随转角变化","feedback":"错：旋转导体感应电势依位置改变，不能把电刷输出直接当作线圈内部波形。"},{"id":"b","text":"换向器周期改变线圈与外电路的连接，电刷收集的电压极性不随每半周交替反转","feedback":"对：机械整流使外端口在理想条件下为脉动直流。"},{"id":"c","text":"N极和S极中磁密的方向相同，故无需换向","feedback":"错：绕组局部导体运动方向和磁场方向均有关，换向是关键。"},{"id":"d","text":"电枢绕组没有电流，因此外端口一定是直流","feedback":"错：有电流与否不是换向器产生单向输出的原因。"}],"answer":["b"]},{"id":"dc-test-31-02","course":"electrical-machines","sections":["dc-chapter-test","dc-sec31"],"title":"外部直流与内部交变能否同时存在","type":"multi","prompt":"关于典型有刷直流机，在忽略换向火花并保留真实转子磁化的前提下，选择全部有依据的判断。","steps":["区分外部电刷固定端口与随转子旋转的材料微元。","同一旋转机器的发电与电动机电磁转换机制可逆。","因此内部铁耗与电动时反电势都不能被“直流”二字排除。"],"transfer":"把磁极改成永磁体，电枢内部产生交变磁化这一结论是否必然消失？","skills":["因果与证据","边界与反例"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"区分外部电刷固定端口与随转子旋转的材料微元。","options":[{"id":"a","text":"电刷端直流不能推出转子全部位置的磁密对材料微元都不变","feedback":"对：旋转铁心上的材料点经历空间磁场交替。"},{"id":"b","text":"发电与电动工作使用换向器的物理作用完全无关","feedback":"错：同一机械换向器分别完成端电压整流与转矩方向保持。"},{"id":"c","text":"直流电动机也存在反电动势，且稳定转速时影响电枢电流","feedback":"对：Ea=C_e Φn，在电动机中与电源电压相抗。"},{"id":"d","text":"铁耗只在交流电机中出现，直流电机转子铁心可不叠片","feedback":"错：电枢铁心旋转导致交变磁化，可有涡流与磁滞损耗。"}],"answer":["a","c"]},{"id":"dc-test-31-03","course":"electrical-machines","sections":["dc-chapter-test","dc-sec31"],"title":"并励电动机线路电流怎么分","type":"single","prompt":"并励直流电动机由一组220 V直流电源供电，电枢电流20 A、并励电流1 A。若不考虑其他外支路，电源输入线电流是多少？","steps":["画出电源节点：输入线电流流入电枢支路和并励支路。","按节点电流守恒 I=Ia+If。","将20 A+1 A得到21 A；若换成并励发电机，节点关系应重新画。"],"transfer":"若同一机组改为并励发电机且输出电流20 A、励磁电流1 A，电枢电流是多少？","skills":["建模","推导计算"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"画出电源节点：输入线电流流入电枢支路和并励支路。","options":[{"id":"a","text":"19 A","feedback":"错：电动机输入分流后到电枢和励磁，电源线电流不是差。"},{"id":"b","text":"20 A","feedback":"错：这只是电枢支路电流。"},{"id":"c","text":"21 A","feedback":"对：电动机并励时 I=Ia+If。"},{"id":"d","text":"22 A","feedback":"错：不能将励磁电流重复加两次。"}],"answer":["c"]},{"id":"dc-test-31-04","course":"electrical-machines","sections":["dc-chapter-test","dc-sec31"],"title":"额定电动机的轴端转矩","type":"numeric","prompt":"一台电动机额定端电压220 V、额定输入线电流50 A、额定效率80%、额定转速1000 r/min。全部电输入均由该端口计量。求额定轴输出转矩，单位N·m，允许四舍五入至两位小数。","answer":84.03380995252074,"unit":"N·m","tolerance":0.02,"rubric":["明确电枢、励磁及端口关系","代入前统一单位和参考方向","验证能量/转矩/数量级并写明适用近似"],"steps":["电动机额定功率通常是轴端输出：P2=ηUI=0.8×220×50=8800 W。","将转速转成角速度 Ω=2π×1000/60 rad/s。","T2=P2/Ω≈84.03 N·m，区分轴转矩与电磁转矩。"],"transfer":"如果题面写的是他励电枢输入功率且未计独立励磁电源，能否仍直接按全机效率计算？","skills":["推导计算","建模"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"电动机额定功率通常是轴端输出：P2=ηUI=0.8×220×50=8800 W。"},{"id":"dc-test-31-05","course":"electrical-machines","sections":["dc-chapter-test","dc-sec31"],"title":"发电机与电动机电磁转矩方向","type":"open","prompt":"同一有刷直流机由外力拖动发电，再接直流电源改作电动。用明确的转速正方向比较两种工况下电磁转矩与机械功率的方向。不可只回答“转向相同”或“相反”。","rubric":["明确同一个参考转轴，给出ω和Te的符号含义","说明发电电磁转矩抗外驱动、机器吸收轴端功率","说明电动转矩推动机械负载，Teω符号变化","指出电压/电流参考约定须随工况一致"],"steps":["先固定ω>0代表正转，电磁转矩Te取推动正转为正。","发电运行需要原动机提供正向转矩克服电磁反转矩，因而Teω<0。","电动运行由电磁场向机械端送功，Teω>0；若采用另一套发电机正转矩标量约定须说明。"],"transfer":"若ω<0而Te<0，机器是正向发电还是反向电动？","skills":["解释表达","边界与反例"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"先固定ω>0代表正转，电磁转矩Te取推动正转为正。"},{"id":"dc-test-31-06","course":"electrical-machines","sections":["dc-chapter-test","dc-sec31"],"title":"复励机能否只套一个电流公式","type":"single","prompt":"给出一台复励直流机的铭牌电压、电枢电流、励磁电流，但未给长复励还是短复励接线。能否据此唯一写出线电流？","steps":["从复励结构识别并励绕组和串励绕组。","区别长复励并励在整个端口还是短复励并励在电枢两端。","根据发电/电动状态及明确接线画节点，再定义输入电流。"],"transfer":"同样铭牌参数下，长复励改短复励会改变哪些绕组的实际端电压？","skills":["建模","边界与反例"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"从复励结构识别并励绕组和串励绕组。","options":[{"id":"a","text":"能，因为复励机始终满足I=Ia+If","feedback":"错：复励包含串励/并励两套绕组，节点位置随长复励与短复励不同。"},{"id":"b","text":"不能，须画长/短复励的具体支路节点并确认运行方式","feedback":"对：KCL只对明确的节点有物理意义。"},{"id":"c","text":"能，因为只要有串励绕组就等于Ia=If","feedback":"错：并励支路不必等于串励电流。"}],"answer":["b"]},{"id":"dc-test-32-01","course":"electrical-machines","sections":["dc-chapter-test","dc-sec32"],"title":"a与A不是同一个支路数","type":"single","prompt":"一台正常四极单叠直流机，教材约定 p为极对数、a为并联支路对数，总极数P=2p，总支路数A=2a。以下哪项正确？","steps":["辨别极数2p与极对数p、支路总数2a与支路对数a。","正常单叠满足2a=2p。","四极意味着p=2，故a=2、A=4，不能把电刷个数无条件代替A。"],"transfer":"正常六极单波绕组的a和A各是多少？","skills":["建模","推导计算"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"辨别极数2p与极对数p、支路总数2a与支路对数a。","options":[{"id":"a","text":"p=2，a=2，A=4","feedback":"对：正常单叠总并联支路数等于极数4。"},{"id":"b","text":"p=4，a=4，A=8","feedback":"错：p不是总磁极数。"},{"id":"c","text":"p=2，a=4，A=2","feedback":"错：定义A=2a不能倒置。"},{"id":"d","text":"p=4，a=2，A=4","feedback":"错：虽A正确但极对数p应为2。"}],"answer":["a"]},{"id":"dc-test-32-02","course":"electrical-machines","sections":["dc-chapter-test","dc-sec32"],"title":"单叠与单波的电压电流权衡","type":"multi","prompt":"同一总有效导体数、每极磁通和转速的理想直流机，比较可实现的正常四极单叠和正常单波接法，选出有依据项。","steps":["计算各接法A，再计算Z/A和每支路电流。","单波的串联导体数增多，但允许总电流反而因并联支路减少而降低。","用E Ia近似比较理想电磁功率，验证不出现无来源增益。"],"transfer":"若极数从四极改成六极而仍采用正常单波，支路数是否变化？","skills":["推导计算","边界与反例"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"计算各接法A，再计算Z/A和每支路电流。","options":[{"id":"a","text":"正常单叠A=4，正常单波A=2","feedback":"对：一般正常单波为两个并联支路。"},{"id":"b","text":"改成单波后每支路串联有效导体数增加","feedback":"对：Z/A增大一倍，理想电势也随之增大。"},{"id":"c","text":"改成单波后导体允许电流也自动翻倍","feedback":"错：每根导体允许电流由导体截面与散热等决定，不能从接线改变推出。"},{"id":"d","text":"换绕组接法可在同样物理导体允许电流下凭空把容量增至两倍","feedback":"错：电压与允许总电流互相制约，不能凭拓扑创生功率。"}],"answer":["a","b"]},{"id":"dc-test-32-03","course":"electrical-machines","sections":["dc-chapter-test","dc-sec32"],"title":"六极单叠每支路电流","type":"numeric","prompt":"一台正常六极单叠直流电机，额定电枢总电流72 A，假设对称分流。每条并联支路流过多少电流？单位A。","answer":12,"unit":"A","tolerance":0.001,"rubric":["明确电枢、励磁及端口关系","代入前统一单位和参考方向","验证能量/转矩/数量级并写明适用近似"],"steps":["正常单叠支路总数 A=P=6。","各支路对称分流，i_branch=Ia/A。","72 A /6=12 A；注意a=3只是支路对数。"],"transfer":"若同一导体组可实现正常单波绕组，保持Ia不变时每支路电流会怎样？","skills":["推导计算","建模"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"正常单叠支路总数 A=P=6。"},{"id":"dc-test-32-04","course":"electrical-machines","sections":["dc-chapter-test","dc-sec32"],"title":"四极16元件单叠绕组接线","type":"open","prompt":"一台四极双层单叠绕组，S=K=Qu=16、每虚槽上/下层各有一个元件边。请从1号元件出发说明y1=4、y2=3、y=yc=1如何对应上、下边及换向片接线，并解释四条并联支路如何形成；不得用“16÷4”直接替代布线说明。","rubric":["写出τ=Qu/P=4及节距定义","正确追踪元件1上1槽、下5槽，下一元件上2槽","说明连续换向片1→2及循环16→1","区分电刷短接元件的瞬时状态与稳态支路分区"],"steps":["以1上层出发跨四个虚槽到5下层，再沿端接到2上层。","每个元件按相邻换向片连接，绕组形成闭合链；电刷将闭合链按极性分区。","正常四极单叠在对称工况下有四条并联支路，a=2，不等于串联导体数。"],"transfer":"若电刷物理位置发生改变，元件边几何中性线与换向片接触位置应如何对应？","skills":["建模","解释表达"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"以1上层出发跨四个虚槽到5下层，再沿端接到2上层。","promptHtml":"<p>一台四极双层单叠绕组，S=K=Qu=16、每虚槽上/下层各有一个元件边。请从1号元件出发说明y1=4、y2=3、y=yc=1如何对应上、下边及换向片接线，并解释四条并联支路如何形成；不得用“16÷4”直接替代布线说明。</p><figure class=\"dc-test-figure\"><svg viewBox=\"0 0 620 188\" role=\"img\" aria-label=\"槽层节距局部展开，示例显示虚槽1到6，带两条跨槽连线\" xmlns=\"http://www.w3.org/2000/svg\"><g font-family=\"system-ui,sans-serif\" font-size=\"15\"><rect x=\"30\" y=\"65\" width=\"28\" height=\"58\" fill=\"none\" stroke=\"currentColor\"/><text x=\"44\" y=\"102\" text-anchor=\"middle\" fill=\"currentColor\">1</text><rect x=\"77\" y=\"65\" width=\"28\" height=\"58\" fill=\"none\" stroke=\"currentColor\"/><text x=\"91\" y=\"102\" text-anchor=\"middle\" fill=\"currentColor\">2</text><rect x=\"124\" y=\"65\" width=\"28\" height=\"58\" fill=\"none\" stroke=\"currentColor\"/><text x=\"138\" y=\"102\" text-anchor=\"middle\" fill=\"currentColor\">3</text><rect x=\"171\" y=\"65\" width=\"28\" height=\"58\" fill=\"none\" stroke=\"currentColor\"/><text x=\"185\" y=\"102\" text-anchor=\"middle\" fill=\"currentColor\">4</text><rect x=\"218\" y=\"65\" width=\"28\" height=\"58\" fill=\"none\" stroke=\"currentColor\"/><text x=\"232\" y=\"102\" text-anchor=\"middle\" fill=\"currentColor\">5</text><rect x=\"265\" y=\"65\" width=\"28\" height=\"58\" fill=\"none\" stroke=\"currentColor\"/><text x=\"279\" y=\"102\" text-anchor=\"middle\" fill=\"currentColor\">6</text><rect x=\"312\" y=\"65\" width=\"28\" height=\"58\" fill=\"none\" stroke=\"currentColor\"/><text x=\"326\" y=\"102\" text-anchor=\"middle\" fill=\"currentColor\">7</text><rect x=\"359\" y=\"65\" width=\"28\" height=\"58\" fill=\"none\" stroke=\"currentColor\"/><text x=\"373\" y=\"102\" text-anchor=\"middle\" fill=\"currentColor\">8</text><rect x=\"406\" y=\"65\" width=\"28\" height=\"58\" fill=\"none\" stroke=\"currentColor\"/><text x=\"420\" y=\"102\" text-anchor=\"middle\" fill=\"currentColor\">9</text><rect x=\"453\" y=\"65\" width=\"28\" height=\"58\" fill=\"none\" stroke=\"currentColor\"/><text x=\"467\" y=\"102\" text-anchor=\"middle\" fill=\"currentColor\">10</text><rect x=\"500\" y=\"65\" width=\"28\" height=\"58\" fill=\"none\" stroke=\"currentColor\"/><text x=\"514\" y=\"102\" text-anchor=\"middle\" fill=\"currentColor\">11</text><rect x=\"547\" y=\"65\" width=\"28\" height=\"58\" fill=\"none\" stroke=\"currentColor\"/><text x=\"561\" y=\"102\" text-anchor=\"middle\" fill=\"currentColor\">12</text><path d=\"M44 65 Q129 -5 232 123\" fill=\"none\" stroke=\"var(--accent,currentColor)\" stroke-width=\"3\"/><path d=\"M91 65 Q170 -5 279 123\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-dasharray=\"6 4\"/><text x=\"30\" y=\"155\" fill=\"currentColor\">请从槽层与元件连接规则解释图中两根跨槽曲线</text></g></svg><figcaption>图形只画前两个线圈的槽位跨度，不提供完整换向器展开图。</figcaption></figure>"},{"id":"dc-test-32-05","course":"electrical-machines","sections":["dc-chapter-test","dc-sec32"],"title":"为什么单叠需要均压线","type":"single","prompt":"多极单叠绕组各同极性支路的感应电势由于磁极不均匀而出现差异，均压线的主要用途是什么？","steps":["多并联支路端口电压必须协调，不同磁极的磁通不均会导致各支路电势差。","支路内部需要等电位点之间的均压连接。","均压线改善电流分配与电刷工作条件，不能把其作用理解为增加电势。"],"transfer":"正常单波支路数只有2条时，均压连接的需要与单叠有何区别？","skills":["因果与证据","边界与反例"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"多并联支路端口电压必须协调，不同磁极的磁通不均会导致各支路电势差。","options":[{"id":"a","text":"把全部负载电流从电刷直接旁路掉","feedback":"错：均压线不是短路整个电枢。"},{"id":"b","text":"连接理论等电位点，为支路不平衡电势提供内部均衡通路","feedback":"对：减少环流过度经电刷流动的风险。"},{"id":"c","text":"增加总有效导体数Z","feedback":"错：连接线改变内部均衡电流路径，不增加有效导体。"}],"answer":["b"]},{"id":"dc-test-32-06","course":"electrical-machines","sections":["dc-chapter-test","dc-sec32"],"title":"支路图与实际绕组位置的区别","type":"open","prompt":"给定某四极直流机的“4条并联支路”等效电路图，学生直接据此画出16个线圈在槽内的实际端部连接。请指出这一推理缺少哪些必要信息，并写出检查绕组图的方法。","rubric":["指出等效电路只表示电气串并联而非空间几何","列出槽数、虚槽、层别、节距、元件/换向片编号","说明电刷位置与短路线圈如何核对","解释单叠/单波/复绕不可只用支路数判定"],"steps":["先区分电刷两端电气等效与实际双层槽线圈分布。","构造需规定上/下边及节距、换向片编号和接线方向。","完成后沿闭合回路核对电刷接触位置和极性，再划分对称并联支路。"],"transfer":"改成复叠绕组后总支路数如何随重数变化？需要增加什么绕组资料？","skills":["建模","解释表达"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"先区分电刷两端电气等效与实际双层槽线圈分布。"},{"id":"dc-test-33-01","course":"electrical-machines","sections":["dc-chapter-test","dc-sec33"],"title":"线性磁路中的交轴反应","type":"single","prompt":"电刷在几何中性线上，一台直流机的交轴电枢磁动势使一个极尖增磁、另一极尖去磁；忽略饱和和齿槽。下列哪项最准确？","steps":["在同一空间坐标比较空载场与电枢磁动势。","线性磁路可叠加磁密，增磁/去磁面积理想对称抵消。","即便积分净磁通不变，合成场零点和极尖分布仍改变。"],"transfer":"考虑铁心饱和后，极尖增磁与去磁是否仍等幅？","skills":["因果与证据","边界与反例"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"在同一空间坐标比较空载场与电枢磁动势。","options":[{"id":"a","text":"合成气隙磁密发生畸变，理想情况下每极净磁通近似不变","feedback":"对：在理想对称线性磁化模型中交轴正负增量的极区积分相互抵消。"},{"id":"b","text":"磁通一定增大，因为有一侧极尖增强","feedback":"错：不能只看局部最大值，须积分。"},{"id":"c","text":"磁中性线必然不发生偏移","feedback":"错：磁场零点随合成空间分布改变。"},{"id":"d","text":"电枢反应消失，因为磁通积分不变","feedback":"错：场波形畸变与中性线移动仍然存在。"}],"answer":["a"],"promptHtml":"<p>电刷在几何中性线上，一台直流机的交轴电枢磁动势使一个极尖增磁、另一极尖去磁；忽略饱和和齿槽。下列哪项最准确？</p><figure class=\"dc-test-figure\"><svg viewBox=\"0 0 620 188\" role=\"img\" aria-label=\"一极下理想交轴电枢反应增量的左右正负对称面积示意\" xmlns=\"http://www.w3.org/2000/svg\"><g font-family=\"system-ui,sans-serif\" font-size=\"15\"><path d=\"M38 95H580 M40 26V157\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\"/><path d=\"M85 95L210 37L324 95\" fill=\"none\" stroke=\"var(--accent,currentColor)\" stroke-width=\"3\"/><path d=\"M324 95L437 153L552 95\" fill=\"none\" stroke=\"var(--accent,currentColor)\" stroke-width=\"3\"/><text x=\"187\" y=\"24\" text-anchor=\"middle\" fill=\"currentColor\">+ 增磁</text><text x=\"436\" y=\"178\" text-anchor=\"middle\" fill=\"currentColor\">− 去磁</text><text x=\"575\" y=\"82\" fill=\"currentColor\">位置x</text></g></svg><figcaption>交轴磁场增量的定性示意：线性对称积分可抵消，但空间波形已畸变。</figcaption></figure>"},{"id":"dc-test-33-02","course":"electrical-machines","sections":["dc-chapter-test","dc-sec33"],"title":"区分几何中性线与磁中性线","type":"multi","prompt":"直流电机由空载进入负载，电刷未移动。选出有依据的判断。","steps":["几何中性线是结构参照；磁中性线是磁场零点。","负载使电枢有电流和磁动势，合成磁密变化。","电刷未移动时，电刷相对磁中性线的有效位置可发生变化。"],"transfer":"在装换向极后，主要要改善哪一局部磁场，而非简单将全部主磁极电枢反应消除？","skills":["建模","边界与反例"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"几何中性线是结构参照；磁中性线是磁场零点。","options":[{"id":"a","text":"几何中性线由磁极几何位置决定，不因负载自行旋转","feedback":"对：其定义依机械/极几何布置。"},{"id":"b","text":"物理中性线由合成磁密为零的位置决定，可随负载移动","feedback":"对：电枢反应畸变气隙场。"},{"id":"c","text":"物理中性线移动就证明电刷机械位置同步移动","feedback":"错：固定电刷可与磁中性线偏离。"},{"id":"d","text":"几何中性线和物理中性线必须始终重合，否则电机无法工作","feedback":"错：实际带载可存在偏移，影响换向但并非绝对停止。"}],"answer":["a","b"]},{"id":"dc-test-33-03","course":"electrical-machines","sections":["dc-chapter-test","dc-sec33"],"title":"饱和时磁密为何不能先加","type":"open","prompt":"学生把空载磁密曲线B0(x)和单独电枢磁密Ba(x)直接相加，认为即使铁心饱和仍可得到准确的负载磁密。请逐步说明问题，给出可接受的建模流程并说明验证条件。","rubric":["指出磁动势满足叠加但磁化B(H)通常非线性","给出先相加各来源磁动势再按局部磁化关系求B","说明在理想线性近似下叠加磁密可以成立","给出中性线与每极磁通积分作为核查量"],"steps":["主励磁和电枢电流分别产生磁动势，可按同一空间位置组合。","材料饱和下B对H的关系非线性，因此一般B(F1+F2)不等于B(F1)+B(F2)。","逐点计算合成磁密再定位零点、积分每极磁通，同时报告材料磁化曲线和近似。"],"transfer":"若改为空气隙磁阻占绝对主导且铁心远未饱和，可把哪一步简化？","skills":["建模","解释表达"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"主励磁和电枢电流分别产生磁动势，可按同一空间位置组合。"},{"id":"dc-test-33-04","course":"electrical-machines","sections":["dc-chapter-test","dc-sec33"],"title":"电刷移位与直轴分量","type":"single","prompt":"在同一转向与磁极标号下，电刷由几何中性线移开一个小角度。电枢磁动势怎样变化？","steps":["几何中性线处对称电流层主要产生交轴磁动势。","移刷改变电枢导体电流区间，磁动势合成轴偏转。","将其分解到正交d、q轴，直轴可能助磁或去磁。"],"transfer":"改动旋转方向但保持电刷物理位置不变，原去磁分量的方向判断是否仍有效？","skills":["因果与证据","迁移设计"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"几何中性线处对称电流层主要产生交轴磁动势。","options":[{"id":"a","text":"只会使所有电枢电流增大，磁动势空间轴不变","feedback":"错：刷位改变支路分区，使磁动势分量轴发生变化。"},{"id":"b","text":"除了交轴分量，还会出现沿主极轴的直轴分量","feedback":"对：刷位偏移使电枢磁动势可分解为交轴和直轴。"},{"id":"c","text":"直轴磁动势一定是去磁，与发电电动工况无关","feedback":"错：分量是增磁还是去磁与移刷方向、运行方式及转向有关。"}],"answer":["b"]},{"id":"dc-test-33-05","course":"electrical-machines","sections":["dc-chapter-test","dc-sec33"],"title":"换向极和补偿绕组如何分工","type":"open","prompt":"一台带刷直流机负载增大后出现较严重换向火花，同时主极极尖气隙场畸变。提出两项不同工程措施，分别说明所抵消的磁场区域、励磁电流为何通常与电枢电流有关，及接反的后果。","rubric":["区分主极下电枢反应和换向区短路线圈换向","换向极磁动势主要用于换向区辅助电流反转","补偿绕组用于主极下抵消电枢反应","说明极性必须按工作工况正确串联，接反会恶化"],"steps":["负载越大，电枢安匝及由它产生的扰动一般越大。","换向极置于主极之间，用对应极性磁场补偿换向区反应电势与短路过程。","补偿绕组通常埋于主极极面，抵消主极下的电枢磁动势；两者不可互代。"],"transfer":"为什么把换向极的安匝简单加大并不能保证全部主极下场畸变消失？","skills":["因果与证据","迁移设计"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"负载越大，电枢安匝及由它产生的扰动一般越大。"},{"id":"dc-test-33-06","course":"electrical-machines","sections":["dc-chapter-test","dc-sec33"],"title":"电枢磁动势的物理来源","type":"single","prompt":"若电枢总电流Ia不变，仅将正常单叠改为可实现的单波绕组，为什么不能直接说电枢磁动势必然按总支路数A成比例增大？","steps":["先写每条支路电流Ia/A，而不是把Ia直接放在每根导体上。","同时检查接法对空间电流层和每极导体分配的影响。","电枢磁动势应由安培导体及实际电流方向计算，不能由一个比值直接断言。"],"transfer":"若保持的不是Ia而是单根导体允许电流，比较结果如何改变？","skills":["建模","边界与反例"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"先写每条支路电流Ia/A，而不是把Ia直接放在每根导体上。","options":[{"id":"a","text":"电枢磁动势与导体位置和每根导体中的电流分布有关，不能脱离接线及绕组几何单独套A","feedback":"对：安培导体、空间电流层和刷位共同决定磁动势。"},{"id":"b","text":"所有导体的电流等于电枢端口电流Ia，因此A从不影响","feedback":"错：在对称分流时导体电流为Ia/A。"},{"id":"c","text":"换向片数等于极对数，因此磁动势不变","feedback":"错：换向片数与极对数无必然相等关系。"}],"answer":["a"]},{"id":"dc-test-34-01","course":"electrical-machines","sections":["dc-chapter-test","dc-sec34"],"title":"由极数与支路数计算电枢电势","type":"numeric","prompt":"一台四极正常单叠直流发电机，总有效导体数Z=600、每极有效磁通Φ=0.020 Wb、转速n=1500 r/min。忽略电枢反应与换向压降。求电枢感应电动势Ea，单位V。","answer":300,"unit":"V","tolerance":0.01,"rubric":["选择正确的电枢/磁通及参考方向公式","代入并保持单位一致","检验结果量纲、极限及适用条件"],"steps":["由P=4和正常单叠A=4，串联导体数是Z/A=150。","每根导体平均电势为PΦn/60，故Ea=(PZ/60A)Φn。","代入得到(4×600/(60×4))×0.02×1500=300 V。"],"transfer":"若绕组改为可实现的正常单波，保持其余量不变，Ea会增大到多少？","skills":["推导计算","建模"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"由P=4和正常单叠A=4，串联导体数是Z/A=150。"},{"id":"dc-test-34-02","course":"electrical-machines","sections":["dc-chapter-test","dc-sec34"],"title":"电磁转矩的极对数与支路数系数","type":"numeric","prompt":"承接上一题P=4、A=4、Z=600、Φ=0.020 Wb，但本题为电动状态，电枢电流Ia=30 A。忽略电枢反应，求平均电磁转矩Te的大小，单位N·m。","answer":57.29577951308232,"unit":"N·m","tolerance":0.02,"rubric":["选择正确的电枢/磁通及参考方向公式","代入并保持单位一致","检验结果量纲、极限及适用条件"],"steps":["从每根导体F=Bli和半径D/2求转矩，再在理想均匀等效场下求和。","用Te=(PZ/(2πA))ΦIa，注意A是总并联支路数。","代入600/(2π)×0.02×30≈57.30 N·m。"],"transfer":"同样Ia下磁通减半、电枢导体数不变，平均转矩怎样变化？","skills":["推导计算","建模"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"从每根导体F=Bli和半径D/2求转矩，再在理想均匀等效场下求和。"},{"id":"dc-test-34-03","course":"electrical-machines","sections":["dc-chapter-test","dc-sec34"],"title":"励磁电流与主磁通不能随便替代","type":"single","prompt":"一台直流发电机处于明显磁饱和区，转速保持不变。励磁电流If降低10%，仅知道这个条件，可以唯一求Ea降低百分之多少吗？","steps":["Ea=Ce Φn，n固定只能说明Ea跟Φ成正比。","磁通Φ由励磁电流If和磁路饱和状态共同决定。","没有给Φ(If)关系时不能从If下降10%推断Ea一定下降10%。"],"transfer":"若题目额外写出Φ与If成比例且各条件不变，答案才是多少？","skills":["边界与反例","推导计算"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"Ea=Ce Φn，n固定只能说明Ea跟Φ成正比。","options":[{"id":"a","text":"能，电势必然降低10%","feedback":"错：只有Φ与If成正比的线性磁化区才可直接等比。"},{"id":"b","text":"不能；Ea与Φ成正比，但If至Φ需额外给磁化曲线或工作点","feedback":"对：磁通可能随If非线性变化。"},{"id":"c","text":"能，电势与励磁电流平方成正比","feedback":"错：并无普适平方律。"},{"id":"d","text":"不能，因为感应电势只与Ia有关","feedback":"错：Ea受Φ和n决定，而非只受Ia控制。"}],"answer":["b"]},{"id":"dc-test-34-04","course":"electrical-machines","sections":["dc-chapter-test","dc-sec34"],"title":"E、T与电磁功率的交叉核查","type":"multi","prompt":"统一采用n为r/min、Ω为rad/s、P为极数、A为总支路数。选择全部正确的理想平均模型等式。","steps":["以有效导体数和每极磁通推得电势式。","再由磁场力或能量关系推得转矩式。","验证CT/Ce=30/π且Ω=2πn/60，得到EaIa=TeΩ。"],"transfer":"若把速度改为rad/s重新定义电势常数，新的转矩常数是否仍不相等？","skills":["推导计算","边界与反例"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"以有效导体数和每极磁通推得电势式。","options":[{"id":"a","text":"Ea=(PZ/(60A))Φn","feedback":"对：支路串联导体数Z/A乘单导体平均电势。"},{"id":"b","text":"Te=(PZ/(2πA))ΦIa","feedback":"对：各导体受力转矩求和，电流按A支路分配。"},{"id":"c","text":"EaIa=Te Ω","feedback":"对：机电转换功率守恒（方向用一致的符号）。"},{"id":"d","text":"若写Ea=CeΦn、Te=CTΦIa，则CT=Ce","feedback":"错：n和Ω单位不同，CT/Ce=30/π。"}],"answer":["a","b","c"]},{"id":"dc-test-34-05","course":"electrical-machines","sections":["dc-chapter-test","dc-sec34"],"title":"为什么电势与转矩常数相关","type":"open","prompt":"从电枢电势Ea=CeΦn与电磁转矩Te=CTΦIa出发，独立推导CT/Ce的值及其物理意义。请明确速度单位，给出一个功率量纲核查。","rubric":["指出n是机械转速r/min、Ω=2πn/60","由EaIa=TeΩ逐项消去Φ、n、Ia","推导CT/Ce=30/π而非1","说明若电势定义以Ω为自变量，SI下常数可相同"],"steps":["由电磁转换功率两侧相等，CeΦnIa=CTΦIa×2πn/60。","只要n、Φ、Ia非零，可约去公共因子，得CT/Ce=60/(2π)=30/π。","它来自转速单位换算，不是两套独立经验常数；用N·m·rad/s与W作维度核查。"],"transfer":"如果将Ea定义为k_eΦΩ、Te=k_tΦIa，两常数应有什么关系？","skills":["推导计算","解释表达"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"由电磁转换功率两侧相等，CeΦnIa=CTΦIa×2πn/60。"},{"id":"dc-test-34-06","course":"electrical-machines","sections":["dc-chapter-test","dc-sec34"],"title":"电势与磁通、转速同时变化","type":"single","prompt":"固定绕组连接，某直流机每极磁通变为原来的0.9倍、机械转速变为原来的1.1倍。忽略电枢反应，其感应电势变为原来的多少倍？","steps":["保持接线常数Ce不变。","Ea2/Ea1=(Φ2/Φ1)(n2/n1)。","代入0.9×1.1=0.99，电势略降1%。"],"transfer":"若只给励磁电流降10%，不再给磁通变化，还能得到0.99倍吗？","skills":["推导计算","边界与反例"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"保持接线常数Ce不变。","options":[{"id":"a","text":"1.00倍","feedback":"错：0.9×1.1=0.99，不是1。"},{"id":"b","text":"0.99倍","feedback":"对：Ea与Φ和n的乘积成正比。"},{"id":"c","text":"0.90倍","feedback":"错：遗漏转速变化。"},{"id":"d","text":"1.10倍","feedback":"错：遗漏磁通变化。"}],"answer":["b"]},{"id":"dc-test-35-01","course":"electrical-machines","sections":["dc-chapter-test","dc-sec35"],"title":"电刷压降计算为什么常被多扣","type":"single","prompt":"某他励直流电动机按稳态平均模型计算，题中明确Ra=0.5Ω是包含电刷接触等效电阻的电枢总电阻。以下哪式可直接使用？","steps":["先询问题目Ra所包括的物理损耗。","若刷压降显式另给，才采用U=Ea+IaR_w+Ub的模型。","若Ra已含刷接触等效电阻，直接U=Ea+IaRa，不可重复加Ub。"],"transfer":"若题目只给纯绕组电阻Ra及电刷总接触压降2 V，如何改写方程？","skills":["建模","边界与反例"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"先询问题目Ra所包括的物理损耗。","options":[{"id":"a","text":"U=Ea+IaRa","feedback":"对：Ra已经包含刷接触等效损耗，不再另扣刷压降。"},{"id":"b","text":"U=Ea+IaRa+2ΔUs，且2ΔUs为同一刷接触的压降","feedback":"错：重复计入了同一物理损耗。"},{"id":"c","text":"U=Ea−IaRa","feedback":"错：这是电动状态电流参考方向下不正确的压降符号。"},{"id":"d","text":"Ea=U+IaRa","feedback":"错：与所选电动状态能量方向相矛盾。"}],"answer":["a"]},{"id":"dc-test-35-02","course":"electrical-machines","sections":["dc-chapter-test","dc-sec35"],"title":"发电机内部电势与端压","type":"numeric","prompt":"一台他励直流发电机稳态输出电枢电流20 A，电枢绕组电阻0.50Ω且不含电刷损耗，电刷总接触压降2.0 V。电枢内部电势为240 V，求电刷外端口电压U，单位V。","answer":228,"unit":"V","tolerance":0.01,"rubric":["选择正确的电枢/磁通及参考方向公式","代入并保持单位一致","检验结果量纲、极限及适用条件"],"steps":["发电机由内部电势扣除导体电阻压降和电刷总接触压降。","U=Ea−IaR_w−Ub，R_w与Ub不重复计入。","240−20×0.5−2=228 V，端压应低于内部电势。"],"transfer":"如果数据给的是已经包含刷接触等效电阻的Ra，应如何避免重复记账？","skills":["推导计算","建模"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"发电机由内部电势扣除导体电阻压降和电刷总接触压降。"},{"id":"dc-test-35-03","course":"electrical-machines","sections":["dc-chapter-test","dc-sec35"],"title":"电磁功率不等于轴端功率","type":"numeric","prompt":"他励直流电动机电枢端电压220 V、电枢电流40 A，电枢总等效电阻（已含电刷接触）0.50Ω。空载机械与铁耗在此工作点合计600 W，其余损耗忽略，励磁输入独立且不计入本题轴端求值。求轴端机械输出功率，单位kW。","answer":7.4,"unit":"kW","tolerance":0.001,"rubric":["选择正确的电枢/磁通及参考方向公式","代入并保持单位一致","检验结果量纲、极限及适用条件"],"steps":["电动状态内部电势Ea=U−IaRa=220−40×0.5=200 V。","电磁转换功率Pem=EaIa=200×40=8000 W。","扣除机械与铁耗600 W得到Pshaft=7400 W=7.4 kW；如算全机效率还需励磁电源输入。"],"transfer":"若题目把600 W改为轴端负载损耗与励磁损耗混合，哪些项目不能再重复扣？","skills":["推导计算","建模"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"电动状态内部电势Ea=U−IaRa=220−40×0.5=200 V。"},{"id":"dc-test-35-04","course":"electrical-machines","sections":["dc-chapter-test","dc-sec35"],"title":"独立励磁的全机效率应计哪些输入","type":"multi","prompt":"一台他励直流电动机电枢由独立220 V电源供电，励磁由独立110 V电源供电，题目要求“整台电机效率”。选择全部有依据项。","steps":["先画独立电枢和励磁两路输入边界。","定义Ptotal=UaIa+UfIf（必要时加其他驱动输入）。","电磁转换与轴输出之间还有旋转相关损耗，分项不重复计。"],"transfer":"当励磁由同一端口并励供电时，总输入与电枢电流之间的关系如何重写？","skills":["建模","边界与反例"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"先画独立电枢和励磁两路输入边界。","options":[{"id":"a","text":"应将电枢供电输入与励磁供电输入同时纳入总输入功率","feedback":"对：两路电源都为机器提供电能。"},{"id":"b","text":"可以直接把轴输出除以UaIa而不说明遗漏励磁输入","feedback":"错：只得到与电枢端口相关的比值，不是包含励磁的全机效率。"},{"id":"c","text":"电刷损耗与绕组铜耗应避免用总电阻和显式刷压降重复计入","feedback":"对：电功率账不可重复扣同一损耗。"},{"id":"d","text":"电磁功率EaIa必然等于轴机械输出功率","feedback":"错：仍有机械、铁耗及其他旋转损耗。"}],"answer":["a","c"]},{"id":"dc-test-35-05","course":"electrical-machines","sections":["dc-chapter-test","dc-sec35"],"title":"给出不会重复计算的功率流","type":"open","prompt":"一台他励直流电动机有独立励磁、非零电枢铜耗、刷损耗、铁耗、机械损耗、杂散损耗。请画或逐行写完整功率流，定义总输入、电磁转换功率、轴端输出和效率，并说明把“空载损耗”误当作一条单独新增支出的危险。","rubric":["说明电枢输入与独立励磁输入的不同端口","正确划分电磁转换之前的电枢铜耗和刷损耗","正确划分电磁转换后铁耗/机械及声明的杂散部分","说明空载损耗集合不能与其组成项重复求和","给出功率守恒与效率核查"],"steps":["先画两个电输入口，不能将励磁功率塞进EaIa。","从UaIa扣除Ia²Ra及显式刷损耗得到Pem=EaIa，再按损耗模型扣除机械、铁耗、杂散求轴输出。","各项定义必须互斥；若p0已等于机械与铁耗之和，就不能再另外各扣一次。"],"transfer":"若为发电状态，功率流箭头和机械输入、电输出两个端口应如何调换？","skills":["建模","解释表达"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"先画两个电输入口，不能将励磁功率塞进EaIa。"},{"id":"dc-test-35-06","course":"electrical-machines","sections":["dc-chapter-test","dc-sec35"],"title":"电动转矩与发电转矩的符号","type":"single","prompt":"固定Ω>0为正转、Te正向定义为推动正转，电枢处于稳态并且TeΩ<0。该电磁转换处于什么状态？","steps":["TeΩ是电磁侧到机械侧的功率定义。","若Ω>0、TeΩ<0，则Te<0，电磁转矩阻碍转轴正转。","机械能进入磁场并经电端输出，是发电/电磁制动方向。"],"transfer":"若Ω<0、Te<0，则TeΩ>0，此时是正向发电还是反向电动？","skills":["因果与证据","边界与反例"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"TeΩ是电磁侧到机械侧的功率定义。","options":[{"id":"a","text":"电动转换，电磁转矩推动转轴","feedback":"错：TeΩ<0表明电磁转矩从机械侧吸收功。"},{"id":"b","text":"发电转换，电磁转矩阻碍当前正转","feedback":"对：电磁机向电端转换机械功，转矩对转速为制动作用。"},{"id":"c","text":"只能由Ea与电刷压降大小直接判定","feedback":"错：本题已给功率流符号，足以判别转换方向。"}],"answer":["b"]},{"id":"dc-test-36-01","course":"electrical-machines","sections":["dc-chapter-test","dc-sec36"],"title":"并励发电机自励的条件","type":"single","prompt":"一台直流并励发电机由原动机带至某转速，剩磁存在，但磁场绕组接线方向产生的励磁磁动势反向抵消剩磁。最可能发生什么？","steps":["剩磁先提供微小初始电势。","小电势驱动并励电流后应帮助而非削弱初始磁通。","若反馈为负，电压无法正常建立，须检查接线及电阻、转速条件。"],"transfer":"若励磁极性正确但总励磁电阻超过该转速的临界值，是否必然成功建压？","skills":["因果与证据","边界与反例"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"剩磁先提供微小初始电势。","options":[{"id":"a","text":"立刻自励到额定电压，因为有剩磁","feedback":"错：正反馈需要励磁帮助剩磁而不是抵消。"},{"id":"b","text":"不能按预期方向建立正常高电压，需检查励磁极性","feedback":"对：正确极性是自励建立的必要条件。"},{"id":"c","text":"励磁电阻无论多大都能自励","feedback":"错：仍有临界电阻和转速等限制。"},{"id":"d","text":"励磁绕组短路必然是正确起动措施","feedback":"错：短路不能替代正确励磁回路及限流。"}],"answer":["b"]},{"id":"dc-test-36-02","course":"electrical-machines","sections":["dc-chapter-test","dc-sec36"],"title":"发电机三种特性不能混用","type":"multi","prompt":"下列有关直流发电机运行特性及条件的说法，选择全部有依据项。","steps":["先区分自变量：If、IL及端压或输出。","把每条曲线的固定条件写在符号旁。","并励使If=U/Rf，负载变化反馈到磁通，不能复制他励直线。"],"transfer":"如果转速变化、励磁电阻固定，原空载曲线与电阻线交点如何变化？","skills":["建模","推导计算"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"先区分自变量：If、IL及端压或输出。","options":[{"id":"a","text":"空载特性E0=f(If)通常在指定转速下测量","feedback":"对：空载磁化曲线在转速固定条件下定义。"},{"id":"b","text":"外特性U=f(IL)须说明转速和励磁方式等保持条件","feedback":"对：他励、并励与复励的外特性形状可能不同。"},{"id":"c","text":"调整特性测量端压恒定时If随IL怎样变化","feedback":"对：指定转速与端电压下找维持端压的励磁电流。"},{"id":"d","text":"任何并励发电机外特性均与他励严格相同","feedback":"错：并励的If会随端压变化形成反馈。"}],"answer":["a","b","c"]},{"id":"dc-test-36-03","course":"electrical-machines","sections":["dc-chapter-test","dc-sec36"],"title":"并励发电机电枢电流反推","type":"numeric","prompt":"一台并励直流发电机负载端电压220 V，负载电流10 A，并励总电阻220Ω，励磁直接并联于端口。求电枢绕组电流Ia，单位A。","answer":11,"unit":"A","tolerance":0.001,"rubric":["选择正确的电枢/磁通及参考方向公式","代入并保持单位一致","检验结果量纲、极限及适用条件"],"steps":["励磁支路电流If=U/Rf=220/220=1 A。","发电机电枢供给负载与本机励磁支路，Ia=IL+If。","所以Ia=10+1=11 A，不是9 A。"],"transfer":"若相同接线换成并励电动机，输入线电流为10 A时Ia如何求？","skills":["推导计算","建模"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"励磁支路电流If=U/Rf=220/220=1 A。"},{"id":"dc-test-36-04","course":"electrical-machines","sections":["dc-chapter-test","dc-sec36"],"title":"磁化曲线和励磁电阻线的交点","type":"open","prompt":"课件给出直流并励发电机自励过程。自行描述应如何绘制空载磁化曲线E0(If)与励磁电阻线RfIf，并讨论剩磁、接线极性、临界励磁电阻和临界转速。指出为什么“有交点”不等于必定有额定电压。","rubric":["写清横轴If、纵轴电势/励磁电阻电压","描述剩磁启动和正反馈的励磁方向","解释较大Rf和较低n对建压的限制","区分低压交点与正常高电压稳定工作点","指出铁心饱和与交点附近稳定性作用"],"steps":["起始剩磁电势使励磁回路有微小If，若极性助磁则E0增加。","用给定n的磁化曲线与直线RfIf找稳态交点，斜率关系影响局部稳定。","高Rf或低n可能只剩近零交点，不能等同于有正常额定高压输出。"],"transfer":"若负载在建压过程中直接重接，终端电压和励磁反馈可能怎样改变？","skills":["建模","解释表达"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"起始剩磁电势使励磁回路有微小If，若极性助磁则E0增加。","promptHtml":"<p>课件给出直流并励发电机自励过程。自行描述应如何绘制空载磁化曲线E0(If)与励磁电阻线RfIf，并讨论剩磁、接线极性、临界励磁电阻和临界转速。指出为什么“有交点”不等于必定有额定电压。</p><figure class=\"dc-test-figure\"><svg viewBox=\"0 0 620 188\" role=\"img\" aria-label=\"并励发电机空载磁化曲线与励磁电阻线示意交点\" xmlns=\"http://www.w3.org/2000/svg\"><g font-family=\"system-ui,sans-serif\" font-size=\"15\"><path d=\"M54 154V23 M54 154H584\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><path d=\"M54 153C80 45 155 25 250 27S490 33 563 33\" fill=\"none\" stroke=\"var(--accent,currentColor)\" stroke-width=\"3\"/><path d=\"M54 154L388 20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-dasharray=\"7 5\"/><text x=\"387\" y=\"18\" fill=\"currentColor\">励磁电阻线</text><text x=\"380\" y=\"52\" fill=\"currentColor\">磁化曲线</text><text x=\"12\" y=\"22\" fill=\"currentColor\">E</text><text x=\"560\" y=\"174\" fill=\"currentColor\">If</text></g></svg><figcaption>独立绘制的无量纲定性曲线；实际交点和临界条件必须由真实磁化数据求出。</figcaption></figure>"},{"id":"dc-test-36-05","course":"electrical-machines","sections":["dc-chapter-test","dc-sec36"],"title":"积复励是否保证端压一定上升","type":"single","prompt":"一台积复励直流发电机随负载增大串励磁动势增强，端压是否必然升高？","steps":["负载增大首先带来电枢电流和内部压降变化。","积复励串励磁动势可能提高有效磁通和内部电势。","端压最终由内部电势增量减去压降增量决定，不能仅凭“积”定方向。"],"transfer":"把积复励绕组反接成差复励，对外特性趋势会有什么改变？","skills":["因果与证据","边界与反例"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"负载增大首先带来电枢电流和内部压降变化。","options":[{"id":"a","text":"必然升高，因为串励安匝上升","feedback":"错：内阻降、电枢反应及饱和可能超过补偿量。"},{"id":"b","text":"不一定，需比较磁通补偿幅度与内部压降、饱和","feedback":"对：可欠复励、平复励或过复励。"},{"id":"c","text":"必然下降，因为所有发电机都只有下降外特性","feedback":"错：过复励可能令端压升高。"}],"answer":["b"]},{"id":"dc-test-36-06","course":"electrical-machines","sections":["dc-chapter-test","dc-sec36"],"title":"源题型迁移：发电机电压崩落诊断","type":"open","prompt":"某并励发电机按规定转向由原动机驱动，空载时能建立电压；接入负载后端压急剧下降而非按近似直线缓降。请给至少三种可能机制，并设计可区分它们的测量/调整顺序。","rubric":["区分电枢IR压降与电枢反应磁通下降","指出并励If=U/Rf的正反馈使电压进一步下降","考虑速度下降、励磁回路接触/电阻变化等原因","提出先检查n、U、If、Ia及负载的实际测量步骤","明确不把所有原因误写成单一固定内阻"],"steps":["确认转速是否保持，排除原动机速度掉落造成的电势降低。","同步量测端压、励磁电流与电枢电流，判断并励反馈是否导致If随U下跌。","再通过改变负载/励磁回路区分压降、电枢反应、磁化饱和或接触问题。"],"transfer":"若换成独立励磁的他励发电机且If固定，同样负载电流下哪条反馈链会消失？","skills":["迁移设计","解释表达"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"确认转速是否保持，排除原动机速度掉落造成的电势降低。"},{"id":"dc-test-37-01","course":"electrical-machines","sections":["dc-chapter-test","dc-sec37"],"title":"恒磁通机械特性为何近似直线","type":"single","prompt":"他励直流电动机恒定U和Φ、忽略电枢反应，按稳态平均模型，哪种转速—电磁转矩曲线正确？","steps":["从电压平衡U=CeΦn+IaRa出发。","由Te=CTΦIa消去Ia。","得到截距U/(CeΦ)与负斜率−Ra/(CeCTΦ²)。"],"transfer":"在U和Φ恒定时增大串联外电阻Rext，曲线截距还是斜率先改变？","skills":["推导计算","解释表达"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"从电压平衡U=CeΦn+IaRa出发。","options":[{"id":"a","text":"n随着Te增大沿直线下降，其斜率幅值与Ra有关","feedback":"对：消去Ia得n=U/(CeΦ)−Ra Te/(CeCTΦ²)。"},{"id":"b","text":"n随着Te增大沿直线上升，因为转矩推动转子","feedback":"错：负载加大引起Ia上升、内部电压降增大，速度通常下降。"},{"id":"c","text":"n完全不受Te影响，因为电枢励磁分开","feedback":"错：IaRa电压降随转矩变。"},{"id":"d","text":"曲线必然是n∝1/√Te","feedback":"错：该近似属于未饱和串励机而非恒磁通他励。"}],"answer":["a"],"promptHtml":"<p>他励直流电动机恒定U和Φ、忽略电枢反应，按稳态平均模型，哪种转速—电磁转矩曲线正确？</p><figure class=\"dc-test-figure\"><svg viewBox=\"0 0 620 188\" role=\"img\" aria-label=\"恒磁通电动机速度n对电磁转矩Te近似负斜率直线\" xmlns=\"http://www.w3.org/2000/svg\"><g font-family=\"system-ui,sans-serif\" font-size=\"15\"><path d=\"M54 155V20 M54 155H581\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><path d=\"M83 39L538 138\" fill=\"none\" stroke=\"var(--accent,currentColor)\" stroke-width=\"3\"/><text x=\"15\" y=\"21\" fill=\"currentColor\">n</text><text x=\"554\" y=\"173\" fill=\"currentColor\">Te</text><text x=\"105\" y=\"26\" fill=\"currentColor\">n₀</text><text x=\"320\" y=\"100\" fill=\"currentColor\">恒定U、Φ</text></g></svg><figcaption>理想他励电动机机械特性示意。改变电阻与电压时需分别判断斜率和截距。</figcaption></figure>"},{"id":"dc-test-37-02","course":"electrical-machines","sections":["dc-chapter-test","dc-sec37"],"title":"负载增大后他励机新转速","type":"numeric","prompt":"一台他励直流电动机电枢端电压240 V、总电枢电阻0.40Ω、主磁通恒定。工作点1：Ia1=20 A、n1=1200 r/min。负载增加后稳态Ia2=30 A，忽略其他变化，求n2，单位r/min。","answer":1179.3103448275863,"unit":"r/min","tolerance":0.02,"rubric":["写出两个稳态点的电势/转矩方程","确认输入、磁通、电枢电流及角速度单位","数值复核并解释近似条件与实际限制"],"steps":["第一工作点内部电势E1=240−20×0.4=232 V。","第二工作点E2=240−30×0.4=228 V。","恒磁通时E∝n，所以n2=1200×228/232≈1179.31 r/min。"],"transfer":"若同时出现电枢反应引起磁通下降，速度比这一估计偏高还是偏低？需要哪些额外条件？","skills":["推导计算","建模"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"第一工作点内部电势E1=240−20×0.4=232 V。"},{"id":"dc-test-37-03","course":"electrical-machines","sections":["dc-chapter-test","dc-sec37"],"title":"串励电动机为何不能空载","type":"single","prompt":"未饱和串励直流电动机励磁通量与电枢电流近似成正比，当轴负载很小，其危险在哪里？","steps":["低负载需要较小Te，未饱和时Te∝Ia²，于是Ia小。","主磁通Φ∝Ia也小，而电势Ea=CeΦn需接近电源端电压。","因此n可能升得很高，不能把该比例律外推至无限速度；实际受剩磁、损耗和机械限制。"],"transfer":"若加装恒速负载或过速保护，风险如何改变？","skills":["因果与证据","边界与反例"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"低负载需要较小Te，未饱和时Te∝Ia²，于是Ia小。","options":[{"id":"a","text":"电枢电流小使磁通很弱，必须用很高转速建立所需反电动势，存在超速风险","feedback":"对：负载转矩小时Ia和Φ减小，速度可升高到危险水平。"},{"id":"b","text":"电枢电流小则转速一定为零","feedback":"错：小负载与高转速并不矛盾。"},{"id":"c","text":"由于串励绕组短路，电机必然不转","feedback":"错：串励绕组与电枢串接并不等于短路。"},{"id":"d","text":"串励电动机在任何小负载下均保持额定转速","feedback":"错：其机械特性通常较软。"}],"answer":["a"]},{"id":"dc-test-37-04","course":"electrical-machines","sections":["dc-chapter-test","dc-sec37"],"title":"串励机的根号关系条件","type":"multi","prompt":"在串励电动机未饱和、忽略电枢压降且磁通与Ia成正比的近似下，选择所有正确推论。","steps":["设未饱和Φ=kIa，将其代入Te=CTΦIa得Te=CT k Ia²。","Ea≈U，速度n≈U/(Ce k Ia)。","消去Ia得到n∝1/√Te；讨论实际饱和、内部压降和机械损耗破坏近似。"],"transfer":"磁化进入饱和区后Te与Ia的依赖关系更接近线性还是平方？","skills":["推导计算","边界与反例"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"设未饱和Φ=kIa，将其代入Te=CTΦIa得Te=CT k Ia²。","options":[{"id":"a","text":"Te与Ia²近似成正比","feedback":"对：Te=CTΦIa而Φ∝Ia。"},{"id":"b","text":"n与1/√Te近似成正比","feedback":"对：Ea≈U恒定，n≈U/(CeΦ)，Ia∝√Te。"},{"id":"c","text":"n与1/Te精确成正比","feedback":"错：少了平方根且忽略压降不是精确全区关系。"},{"id":"d","text":"进入磁饱和后仍可全区沿用Te∝Ia²","feedback":"错：饱和时Φ随Ia的增长减缓。"}],"answer":["a","b"]},{"id":"dc-test-37-05","course":"electrical-machines","sections":["dc-chapter-test","dc-sec37"],"title":"机电平衡点是否稳定","type":"open","prompt":"给出一台直流电动机的稳态机械特性Te(ω)与负载转矩TL(ω)，在交点ω*满足Te=TL。推导单状态机械方程中的局部稳定性斜率判据，并说明为何不能只看电机曲线下降而忽略负载。","rubric":["列出J dω/dt=Te(ω)−TL(ω)（可计已说明损耗）","平衡点满足净转矩为零","微小扰动线性化得d(Te−TL)/dω<0趋向恢复","指出电流、电感或控制器动态存在时需多状态分析"],"steps":["从净加速转矩定义动力学Jω点=Te−TL。","在平衡点附近令ω=ω*+δω，线性化为Jδω点≈(Te'−TL')δω。","若该系数为负，正扰动产生减速、负扰动产生加速；非稳态控制需更完整模型。"],"transfer":"若负载为恒功率机械负载TL=P/ω，低速附近稳定性为何必须重新检查？","skills":["推导计算","解释表达"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"从净加速转矩定义动力学Jω点=Te−TL。"},{"id":"dc-test-37-06","course":"electrical-machines","sections":["dc-chapter-test","dc-sec37"],"title":"并励机失磁：瞬态和长期状态","type":"open","prompt":"一台他励或并励直流电动机正常运行，励磁回路突然开路且仍有电枢电源。分别解释失磁瞬间电枢电流变化趋势、随后的转速风险及起动前失磁的不同后果；不得只回答“失磁必然转速增大”。","rubric":["用Ea=CeΦn说明瞬时磁通降低对反电动势的影响","结合电枢电感说明电流不会在数学瞬间跳变","说明Te=CTΦIa及负载/保护制约转速后续响应","解释无励磁起动时可能过流且转矩不足","提出失磁检测、过流与超速保护措施"],"steps":["突然失磁时转速不能立刻改变，Φ下降使反电势目标值降低。","电枢电感使电流连续但可很快上升，随后Te与机械负载决定加速、停转或失稳。","轻负载时存在高速危险，重负载时可能扭矩不足，必须综合负载与保护，而非一概宣称稳定超速。"],"transfer":"若改成串励电动机，断开励磁绕组会发生什么电路变化？","skills":["因果与证据","迁移设计"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"突然失磁时转速不能立刻改变，Φ下降使反电势目标值降低。"},{"id":"dc-test-38-01","course":"electrical-machines","sections":["dc-chapter-test","dc-sec38"],"title":"起动合闸瞬间电流会跳到U/R吗","type":"single","prompt":"他励直流电动机静止，励磁稳定，电枢电感La明显，初始电流0、在t=0施加恒定电压U，转子暂未转动。哪个判断正确？","steps":["静止时Ea≈0，但电压方程仍有La di/dt。","对初始i(0)=0，U=Ra i+La di/dt给di/dt(0+)=U/La。","堵转准稳态电流U/Ra仅在足够长且转子保持不动时趋近。"],"transfer":"增大La而保持U、Ra不变，最初电流上升斜率怎样变化？","skills":["建模","边界与反例"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"静止时Ea≈0，但电压方程仍有La di/dt。","options":[{"id":"a","text":"t=0+时电流瞬间等于U/Ra","feedback":"错：这是忽略电感的堵转准稳态极限，不是电感存在时的瞬时。"},{"id":"b","text":"t=0+时电流仍为0，初始变化率近似U/La","feedback":"对：电感储能与电流连续性限制电流跃变。"},{"id":"c","text":"t=0+时Ea=U，所以电流不再增加","feedback":"错：Ea与速度有关，零速时Ea=0。"}],"answer":["b"]},{"id":"dc-test-38-02","course":"electrical-machines","sections":["dc-chapter-test","dc-sec38"],"title":"限流起动的最小串联电阻","type":"numeric","prompt":"他励直流电动机已经建立正常励磁，电枢端施加240 V，绕组和电刷等效总电阻0.40Ω。忽略起动瞬间反电势，要求起动电流准稳态估算不超过60 A。至少串入多少Ω的外电阻？","answer":3.6,"unit":"Ω","tolerance":0.001,"rubric":["写出两个稳态点的电势/转矩方程","确认输入、磁通、电枢电流及角速度单位","数值复核并解释近似条件与实际限制"],"steps":["起动初始E≈0，准稳态堵转估算I≈U/(Ra+Rext)。","限流上限60 A对应总电阻240/60=4.0Ω。","额外电阻Rext=4.0−0.4=3.6Ω；有电感时i(0+)=0而不是60 A。"],"transfer":"如果采用受控电压源限流，不串外电阻，可以通过什么参数改变实现相同60 A上限？","skills":["推导计算","建模"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"起动初始E≈0，准稳态堵转估算I≈U/(Ra+Rext)。"},{"id":"dc-test-38-03","course":"electrical-machines","sections":["dc-chapter-test","dc-sec38"],"title":"恒磁通降电枢电压后的转速","type":"numeric","prompt":"某他励电动机在U1=220 V、Ia1=20 A、Ra=0.50Ω、n1=1000 r/min下稳定运行。忽略机械损耗变化，调低电枢端电压至180 V，保持磁通和负载电磁转矩不变，求新稳态转速n2，单位r/min。","answer":809.5238095238095,"unit":"r/min","tolerance":0.02,"rubric":["写出两个稳态点的电势/转矩方程","确认输入、磁通、电枢电流及角速度单位","数值复核并解释近似条件与实际限制"],"steps":["恒Φ且Te不变，Ia2=Ia1=20 A。","E1=220−10=210 V，E2=180−10=170 V。","n2=n1(E2/E1)=1000×170/210≈809.52 r/min。"],"transfer":"若改为串电阻调速且电源仍为220 V，为什么会带来额外损耗？","skills":["推导计算","建模"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"恒Φ且Te不变，Ia2=Ia1=20 A。"},{"id":"dc-test-38-04","course":"electrical-machines","sections":["dc-chapter-test","dc-sec38"],"title":"弱磁调速不等于凭空增功率","type":"multi","prompt":"他励直流机保持最大端电压与电枢电流限值，基速以上采用弱磁。选择全部有依据项。","steps":["电势Ea≈U且固定电压上限时减小Φ倾向于提高速度。","同电流限值时转矩上限按Φ下降；近似TeΩ可保持上限不变。","若指定负载转矩而非限流边界，要重算Ia与压降，检查机械强度、换向和温升。"],"transfer":"弱磁一半但维持相同Te，Ia与铜耗变化比例（只考虑Ia²Ra）怎样？","skills":["因果与证据","边界与反例"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"电势Ea≈U且固定电压上限时减小Φ倾向于提高速度。","options":[{"id":"a","text":"在理想电势接近端电压时，降低Φ有可能提高转速","feedback":"对：n≈U/(CeΦ)，但受内部压降与限速影响。"},{"id":"b","text":"相同电流限值下最大可用电磁转矩随Φ减小","feedback":"对：Te,max=CTΦIa,max。"},{"id":"c","text":"减半磁通后任意负载都能稳稳达到两倍转速","feedback":"错：相同转矩需要更大Ia，电阻压降也变，且受限流/超速约束。"},{"id":"d","text":"基速以上可出现近似恒功率能力区，但不是所有工作点自动恒功率","feedback":"对：受电压与电流上限形成的能力边界而非实际运行曲线。"}],"answer":["a","b","d"]},{"id":"dc-test-38-05","course":"electrical-machines","sections":["dc-chapter-test","dc-sec38"],"title":"三种电磁制动如何区分","type":"single","prompt":"保持正向转速的他励直流电机，哪种描述正确区分回馈、能耗与反接制动？","steps":["Teω<0只表明电磁侧对机械转轴产生制动作用。","看电端连接：回馈到有吸收能力的电源、用电阻消耗、或反向供电反接。","反接制动临近零速时应撤除或切换，否则可能反向起动。"],"transfer":"如果电源仅允许单向输出而不允许吸收电流，能否仅凭Ea>U判定实际已回馈？","skills":["因果与证据","边界与反例"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"Teω<0只表明电磁侧对机械转轴产生制动作用。","options":[{"id":"a","text":"所有电磁制动都把机械能送回直流电网","feedback":"错：能耗制动以电阻发热消耗能量，反接可能还吸收电源功率。"},{"id":"b","text":"回馈需电势及电源/变换器允许的双向功率通路；能耗制动接电阻，反接对制动时机要求严格","feedback":"对：不同制动的电端能量去向不同。"},{"id":"c","text":"反接制动达到零速后不用切换也会稳定停止","feedback":"错：不撤去反接电压可能继续反向加速。"},{"id":"d","text":"能耗制动速度越低电磁转矩必然越大","feedback":"错：依赖转速电势，降速时制动转矩往往下降。"}],"answer":["b"]},{"id":"dc-test-38-06","course":"electrical-machines","sections":["dc-chapter-test","dc-sec38"],"title":"用四象限分析工况而非背名称","type":"open","prompt":"以ω为水平轴、Te为纵轴，说明四个象限Teω的符号；给出正向转速下两种制动的电功率去向。再解释反向旋转时Te<0为何不是发电。","rubric":["正确判别第一、第三象限Teω>0为电动转换","正确判别第二、第四象限Teω<0为电磁制动/发电转换","给出回馈/能耗制动的电端能量去向区别","说明第三象限ω<0且Te<0是反转电动","说明符号取决于明确统一参考轴"],"steps":["先固定ω>0为正转、Te>0为推动正转，按乘积判别转换方向。","第一、第三象限乘积为正，机械侧获得电磁功；第二、第四为负，电磁转矩阻碍当前旋转。","制动是否回馈电源还须看电端连接；负号本身不是发电的充分判据。"],"transfer":"若ω<0但Te>0，此时处于第几象限、力矩作用如何？","skills":["建模","解释表达"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"先固定ω>0为正转、Te>0为推动正转，按乘积判别转换方向。","promptHtml":"<p>以ω为水平轴、Te为纵轴，说明四个象限Teω的符号；给出正向转速下两种制动的电功率去向。再解释反向旋转时Te&lt;0为何不是发电。</p><figure class=\"dc-test-figure\"><svg viewBox=\"0 0 620 188\" role=\"img\" aria-label=\"电磁转矩Te与速度ω四象限转矩功率乘积\" xmlns=\"http://www.w3.org/2000/svg\"><g font-family=\"system-ui,sans-serif\" font-size=\"15\"><path d=\"M52 94H568 M309 13V173\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"/><text x=\"575\" y=\"89\" fill=\"currentColor\">+ω</text><text x=\"316\" y=\"18\" fill=\"currentColor\">+Te</text><text x=\"380\" y=\"45\" fill=\"currentColor\">Ⅰ：ω&gt;0,Te&gt;0</text><text x=\"58\" y=\"45\" fill=\"currentColor\">Ⅱ：ω&lt;0,Te&gt;0</text><text x=\"70\" y=\"149\" fill=\"currentColor\">Ⅲ：ω&lt;0,Te&lt;0</text><text x=\"370\" y=\"149\" fill=\"currentColor\">Ⅳ：ω&gt;0,Te&lt;0</text></g></svg><figcaption>本图的四象限编号按平面坐标标准顺序；判定转换方向使用Teω的符号。</figcaption></figure>"},{"id":"dc-test-38-07","course":"electrical-machines","sections":["dc-chapter-test","dc-sec38"],"title":"如何反转串励直流电动机","type":"single","prompt":"一台串励直流电动机由正向恒定直流电源供电，负载与机械条件不变。要使稳态电磁转矩方向反转，哪种改线思路正确？","steps":["Te方向由磁通极性和电枢电流方向的相对关系决定。","串励机整体换端会使两者同时反向，不导致方向翻转。","要改变转矩符号，须只翻转其中一个，且满足安全换向接线。"],"transfer":"若采用他励机，一般选择改变电枢极性还是励磁极性来反转更合理，为什么？","skills":["因果与证据","迁移设计"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"Te方向由磁通极性和电枢电流方向的相对关系决定。","options":[{"id":"a","text":"把整台串励机的两个外电源端子互换","feedback":"错：串励绕组与电枢电流同时反向，ΦIa乘积方向可能不变。"},{"id":"b","text":"只反转电枢或只反转励磁回路其中一个的极性","feedback":"对：相对磁场与电枢电流的方向必须改变。"},{"id":"c","text":"同时反转电枢与励磁绕组接线","feedback":"错：两者都反向时乘积的符号不变。"}],"answer":["b"]},{"id":"dc-test-38-08","course":"electrical-machines","sections":["dc-chapter-test","dc-sec38"],"title":"比较三种调速的机械特性与代价","type":"open","prompt":"给定一台恒磁通近似成立的他励直流电动机，需要从1000 r/min降到700 r/min并在一定负载变化范围内保持速度。分别比较降电枢电压、串电阻调速与弱磁调速对n–Te曲线截距、斜率、损耗、转矩能力的影响，提出工程选择。","rubric":["从n=U/(CeΦ)−Ra Te/(CeCTΦ²)逐项解释截距与斜率","降电压主要移动截距，配合闭环可提高稳速能力","串电阻增斜率幅值和Ia²Rext损耗，负载变化更敏感","弱磁通常用于提高速度、减小转矩上限，不是降速优选","说明电压、电流、温升、机械限速等实际边界"],"steps":["先固定Φ的机械特性，区分横截距（无载速度）和负斜率。","降电压可整体降速；串电阻使负载速度下降但效率差。","弱磁倾向于提高速度且降低允许转矩，达成负载稳速时须考虑闭环与限流。"],"transfer":"若目标不是降速而是基速以上扩大速度范围，工程优先级会如何改变？","skills":["建模","迁移设计"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"先固定Φ的机械特性，区分横截距（无载速度）和负斜率。"},{"id":"dc-test-39-01","course":"electrical-machines","sections":["dc-chapter-test","dc-sec39"],"title":"短路换向线圈为何可能有火花","type":"single","prompt":"在有刷直流机中，电刷跨接相邻换向片时一段线圈短时被电刷短接，电流应反向。哪种因素会妨碍它在短接时间内完成反向？","steps":["跟踪短路元件从原方向电流变成相反方向的过程。","线圈自感产生阻碍电流变化的电压，方向与电流变化趋势相反。","若离开电刷时电流未反向完毕，断开接触可能发生火花。"],"transfer":"提高转速使换向短路时间更短时，对完成电流反转有何影响？","skills":["因果与证据","建模"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"跟踪短路元件从原方向电流变成相反方向的过程。","options":[{"id":"a","text":"短路线圈电感产生的电抗电势阻碍电流变化","feedback":"对：电感使di/dt受限，过迟换向可能在断开时拉弧。"},{"id":"b","text":"电枢铁心无论转速都保持均匀磁化","feedback":"错：磁化状态不能直接解释电流反转困难。"},{"id":"c","text":"电刷电阻永远为零，所以不存在换向过程","feedback":"错：电刷接触条件对换向重要。"}],"answer":["a"]},{"id":"dc-test-39-02","course":"electrical-machines","sections":["dc-chapter-test","dc-sec39"],"title":"哪些措施改善换向","type":"multi","prompt":"在其他条件相近时，选出有依据的换向改善措施或判断。","steps":["识别换向是短路元件电流反转的动态过程。","从电势与电流变化率分析电抗电势、换向电势和接触电阻。","依据磁场区域区分换向极与主极补偿绕组，不保证单一措施解决所有火花。"],"transfer":"若换向极串联方向接反，负载上升时火花会变轻还是可能加重？","skills":["建模","边界与反例"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"识别换向是短路元件电流反转的动态过程。","options":[{"id":"a","text":"适当换向极磁场可抵消换向区电枢反应并辅助电流反转","feedback":"对：目标是换向区的合适电势。"},{"id":"b","text":"补偿绕组主要针对主极极面下电枢反应，不能自动代替换向极全部作用","feedback":"对：作用位置不同。"},{"id":"c","text":"刷片接触电阻及其变化可影响短路线圈电流分配","feedback":"对：换向还受接触电阻与时间条件。"},{"id":"d","text":"只要励磁更强就一定不会产生换向火花","feedback":"错：换向极性、换向电势、短路线圈电感和接触条件都重要。"}],"answer":["a","b","c"]},{"id":"dc-test-39-03","course":"electrical-machines","sections":["dc-chapter-test","dc-sec39"],"title":"换向过程的时间尺度与电势平衡","type":"open","prompt":"设换向短路线圈自感L、从电流+i过渡到−i，换向短接时间tc。给出平均电流变化率的量级和对应电抗电势量级，解释理想瞬时换向与实际火花之间的差别。","rubric":["给出总电流变化约−2i、平均di/dt≈−2i/tc","给出电抗电势量级L×2i/tc并说明极性阻碍变化","解释电刷与换向片短接时的电流分配","说明速度增大导致tc缩短的风险","提出换向极/合理电刷与接触条件改善措施"],"steps":["短路元件电流从+i转到−i，平均变化量−2i。","短接时间tc内di/dt量级为−2i/tc，自感电势幅值约2Li/tc。","换向极必须建立合适方向的换向电势辅助反向，实际电刷接触不是理想无电阻短路。"],"transfer":"当线圈电流和转速同时加倍、L不变且tc近似减半，电抗电势量级增加多少倍？","skills":["推导计算","迁移设计"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"短路元件电流从+i转到−i，平均变化量−2i。"},{"id":"dc-test-39-04","course":"electrical-machines","sections":["dc-chapter-test","dc-sec39"],"title":"图中的刷位和元件边为何不在同一实物径线上","type":"single","prompt":"课件单叠绕组图把“线圈边处于几何中性线”和“电刷对准换向器相应位置”并列说明。为何不能机械地把电刷画在转子线圈边同一实物径线上？","steps":["先辨认转子槽有效边、线圈端接、换向片和固定电刷四类物理位置。","换向器分片与线圈接线把短路元件联系到特定刷片位置。","图应在同一角位置逻辑中正确映射，而不是把不同截面实体简单重叠。"],"transfer":"在LN已有3D模型里应跟踪哪些对象才能确认短路线圈与电刷位置关系？","skills":["解释表达","建模"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"先辨认转子槽有效边、线圈端接、换向片和固定电刷四类物理位置。","options":[{"id":"a","text":"电刷接触的是换向片，线圈有效边处于槽内；两者经端部连接和换向片位置相联系","feedback":"对：不同实体几何位置需要根据实际接线映射。"},{"id":"b","text":"电刷总是接触电枢铁心而不是换向片","feedback":"错：电刷机械接触的是换向器表面。"},{"id":"c","text":"只要支路数是4，任何电刷与槽的空间对应都可随意","feedback":"错：连接极性和被短接元件必须与实际位置配合。"}],"answer":["a"]},{"id":"dc-test-mix-01","course":"electrical-machines","sections":["dc-chapter-test","dc-worked"],"title":"跨工况：他励降压但电磁转矩不变","type":"numeric","prompt":"本题独立给定：他励直流电动机额定电枢电压240 V、电枢电流30 A、转速1200 r/min，电枢总等效电阻（已含电刷接触）0.60Ω，励磁由独立电源维持磁通不变。电枢端电压降低到200 V，电磁负载转矩保持原值，忽略饱和/其他影响。求新转速，单位r/min。","answer":983.7837837837837,"unit":"r/min","tolerance":0.02,"rubric":["区分额定与改变工况的电枢、励磁电流","建立电压和转矩两个运行点的方程","数值求解并核查电枢压降和磁通假设"],"steps":["E1=240−30×0.60=222 V，固定磁通且Te不变意味着Ia2=30 A。","E2=200−30×0.60=182 V，故n2/n1=E2/E1。","n2=1200×182/222≈983.78 r/min；独立励磁不随电枢端电压变化。"],"transfer":"若改为并励机且励磁绕组也接在200 V端口，磁通不再固定，重算应如何开始？","skills":["建模","推导计算"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"E1=240−30×0.60=222 V，固定磁通且Te不变意味着Ia2=30 A。"},{"id":"dc-test-mix-02","course":"electrical-machines","sections":["dc-chapter-test","dc-worked"],"title":"跨工况：并励降压时必须重算磁通","type":"numeric","prompt":"本题独立给定：并励直流电动机额定端电压240 V、电枢电流30 A、转速1200 r/min，电枢总等效电阻（已含电刷接触）0.60Ω，励磁电阻不变且磁路未饱和。端压降为200 V，仍拖动相同电磁转矩，忽略损耗变化。求新转速，单位r/min。","answer":1157.1891891891892,"unit":"r/min","tolerance":0.03,"rubric":["区分额定与改变工况的电枢、励磁电流","建立电压和转矩两个运行点的方程","数值求解并核查电枢压降和磁通假设"],"steps":["并励If∝U且未饱和，所以Φ2/Φ1=200/240=5/6。","相同Te要求ΦIa不变，Ia2=30×6/5=36 A；E2=200−36×0.6=178.4 V。","n2=n1(E2/E1)(Φ1/Φ2)=1200×(178.4/222)×(6/5)≈1157.19 r/min。"],"transfer":"如果题目只有“励磁电阻不变”，却说明磁路已经饱和，哪些数字无法唯一得出？","skills":["建模","推导计算"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"并励If∝U且未饱和，所以Φ2/Φ1=200/240=5/6。"},{"id":"dc-test-mix-03","course":"electrical-machines","sections":["dc-chapter-test","dc-worked"],"title":"四种常见计算错误一起辨别","type":"multi","prompt":"有刷直流电动机与发电机共用公式，但励磁与功率流参考方向不同。选择所有必有依据的诊断建议。","steps":["先确定电路实际连接及线、电枢和励磁电流分流。","再使用含刷损耗或不含刷损耗的相容电压方程。","最后通过电磁功率与轴功率平衡核查是否遗漏或重复损耗。"],"transfer":"若机组从电动进入回馈制动，怎样保持功率符号在同一坐标下自洽？","skills":["因果与证据","边界与反例"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"先确定电路实际连接及线、电枢和励磁电流分流。","options":[{"id":"a","text":"电枢电流与线电流混用前，应先画他励/并励/复励接线及电流箭头","feedback":"对：电流关系取决于励磁连接和运行状态。"},{"id":"b","text":"已有含刷接触等效电阻时再加同一刷压降，会重复计损耗","feedback":"对：同一物理刷接触不能计两遍。"},{"id":"c","text":"只要n和Ia已知，就不需要磁通、绕组参数也能唯一算Ea与Te","feedback":"错：电势和转矩常数、每极主磁通仍必需。"},{"id":"d","text":"求全机效率应明确是否包含独立励磁供电和各类损耗","feedback":"对：端口边界决定输入功率分母。"}],"answer":["a","b","d"]},{"id":"dc-test-mix-04","course":"electrical-machines","sections":["dc-chapter-test","dc-worked"],"title":"电动机拖发电机：整个传动链的能量账","type":"open","prompt":"一台他励直流电动机驱动他励发电机，电动机本体效率90%，发电机总效率80%，忽略联轴器损耗且励磁输入已分别包含在各自效率的电输入/输出边界中。设发电机给负载提供8 kW电功率。写出电动机电输入、联轴器机械传递功率、发电机机械输入的数值，并画出整条能量流，说明为什么不能将两台效率相加。","rubric":["发电机机械输入8/0.80=10 kW","电动机机械输出/轴传递为10 kW","电动机总电输入10/0.90≈11.11 kW","整体效率为0.9×0.8=72%","说明额定功率与电磁转换功率可能不同"],"steps":["发电机输出8 kW且效率80%，所以轴输入8/0.8=10 kW。","联轴器无损，电动机轴输出10 kW；电动机输入10/0.9≈11.11 kW。","级联系统的输出/输入=8/11.11≈72%，等于两效率相乘而非相加。"],"transfer":"如果励磁电源被排除在效率定义之外，如何修订功率流边界后再求整体效率？","skills":["建模","迁移设计","解释表达"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"发电机输出8 kW且效率80%，所以轴输入8/0.8=10 kW。"},{"id":"dc-test-mix-05","course":"electrical-machines","sections":["dc-chapter-test","dc-worked"],"title":"电机控制方案：效率、保护与稳定性同时考虑","type":"open","prompt":"某机械平台需要0–1000 r/min大范围稳速、快速起动、频繁减速，长期运行中转矩变化较大。采用一台他励有刷直流电机。请给出电枢控制、励磁、起动限流、能耗/回馈制动和失磁过速保护的选择理由，并指出至少三处应采集的状态量。","rubric":["推荐励磁先建立且设置失磁/超速联锁","用可控电枢电压与闭环转速/电流控制而非高损串电阻","按电流限值、热与机械限制制定起动策略","按电源能否吸收功率决定回馈与能耗制动实现","给出电枢电流、转速、励磁电流/温度等测量反馈","说明动态响应不能只用稳态公式代替"],"steps":["先明确基速以下目标，固定励磁时调电枢电压可改变机械特性截距且保持较好的转矩能力。","设计电流限制与励磁失效检测，再给出加速/降速切换策略。","根据直流母线是否可吸收回馈能量选择回馈或能耗制动，并监测温度、速度与电流。"],"transfer":"若用户改为基速以上长期高速运行，弱磁、换向与机械极限将如何加入设计？","skills":["建模","迁移设计","解释表达"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"先明确基速以下目标，固定励磁时调电枢电压可改变机械特性截距且保持较好的转矩能力。"},{"id":"dc-test-mix-06","course":"electrical-machines","sections":["dc-chapter-test","dc-worked"],"title":"一张图串起全章核心物理量","type":"open","prompt":"给出一台正常单叠、恒磁通他励电机的数据P、Z、Φ、n、Ia、Ra。请以“绕组与刷片接线→电枢磁动势与主磁通→感应电势与电磁转矩→电压和能量平衡→负载改变→调速/制动”建立一条可复算的分析链；至少给两种极限或反例检查，并指出现实装置与理想模型的差异。","rubric":["先从绕组支路数、串联导体和刷片作用定义电枢等效对象","写出Ea、Te并用EaIa=TeΩ验证转换功率","给出U−Ea、IaRa和电端/机械端损耗路径","写出不同励磁/负载工况下两个运行点的比较原则","提出至少两种反例（饱和、失磁、电感、限流、刷压降等）","区分课程理论与电刷火花、热极限、机械限速等工程边界"],"steps":["由绕组几何和电刷确定支路数，明确总导体与每支路串联导体的区别。","通过电枢感应电势、导体受力转矩导出机电转换恒等式，再按电压/功率流找工作点。","面对负载变化应重新列电压、转矩和机械动力学；进入饱和、制动或换向不良时明确失效近似。"],"transfer":"若换成正常单波且保持单根导体允许电流，哪两条量必须同时修改才能维持自洽的功率链？","skills":["建模","迁移设计","解释表达"],"origin":"本站原创教学诊断题，所给数值为假设；题源依据参见本章课程参考。","hint":"由绕组几何和电刷确定支路数，明确总导体与每支路串联导体的区别。"}]);
